    'licence_trial_offline_email_body' => 'Olá,<br><br>Este servidor TeamPass (<strong>#tp_fqdn#</strong>) não consegue contatar o servidor de licenças, por isso não pôde solicitar sozinho a avaliação da extensão do navegador.<br><br>Abra o link abaixo em uma máquina com acesso à Internet e depois confirme a solicitação na página:<br><br><a href="#tp_trial_link#">#tp_trial_link#</a><br><br>Em seguida, uma mensagem de confirmação será enviada para <strong>#tp_contact_email#</strong>. Abrir o link que ela contém ativa a avaliação de 30 dias.<br><br>Duas coisas importantes:<br>- uma avaliação é concedida uma única vez por domínio e produto, de forma permanente;<br>- se você pedir uma nova mensagem de confirmação, o link anterior deixa de funcionar.<br><br>Este link contém a chave de licença da sua instância. Não o encaminhe.',
